VARIABLES_INTERVIEW = [
    InterviewQA("Conceptual", "Mutable vs immutable types in Python?", "**Mutable:** list, dict, set, bytearray. **Immutable:** int, float, str, tuple, frozenset, bytes. Immutable objects cannot change after creation; 'modification' creates new objects."),
    InterviewQA("Conceptual", "Difference between `==` and `is`?", "`==` compares **values** (equality). `is` compares **identity** (same object in memory). Use `is` only for singletons like `None`."),
    InterviewQA("Conceptual", "What is dynamic typing?", "Variable names bind to objects at runtime; the same name can refer to different types over time without explicit declaration."),
    InterviewQA("Conceptual", "How do you check type safely?", "Prefer `isinstance(x, int)` over `type(x) == int` because isinstance respects inheritance."),
    InterviewQA("Conceptual", "What is `None`?", "A singleton representing absence of value. Always test with `x is None`."),
    InterviewQA("Operators", "Explain operator precedence.", "Parentheses > exponent > unary > mult/div/mod > add/sub > comparisons > not > and > or. Use parentheses when unsure."),
    InterviewQA("Operators", "What is short-circuit evaluation?", "`and` stops at first falsy; `or` stops at first truthy. Side effects may not run."),
    InterviewQA("Operators", "Difference between `/` and `//`?", "`/` is true division (float). `//` is floor division toward negative infinity."),
    InterviewQA("Strings", "Are strings mutable?", "No. Methods like `.upper()` return **new** strings."),
    InterviewQA("Strings", "f-string vs .format() vs %?", "f-strings (3.6+) are fastest and most readable. `.format()` flexible for templates. `%` is legacy."),
    InterviewQA("Casting", "Why does `0.1 + 0.2 != 0.3`?", "Floating-point binary representation cannot exactly store some decimals. Use `decimal.Decimal` for money."),
    InterviewQA("Casting", "When is `bool('False')` True?", "Any non-empty string is truthy, including `'False'` and `'0'`."),
    InterviewQA("Memory", "What does `id()` return?", "CPython object address (identity). Same id means same object."),
    InterviewQA("Memory", "Copy vs reference for lists?", "Assignment copies reference. Use `.copy()` or `list()` for shallow copy."),
    InterviewQA("Practical", "Swap two variables pythonically?", "`a, b = b, a` using tuple packing/unpacking."),
    InterviewQA("Practical", "Walrus operator use case?", "Assign and use in expression: `if (n := len(data)) > 10:` avoids duplicate computation."),
    InterviewQA("Practical", "Chained comparisons?", "`a < b < c` equivalent to `a < b and b < c`, evaluates b once."),
    InterviewQA("Practical", "What is truthiness?", "Empty containers, zero numbers, None, False are falsy; most else truthy."),
    InterviewQA("Interview", "Explain `isinstance` vs `type` for subclasses.", "`isinstance(obj, Base)` True for subclasses. `type(obj) == Base` False for subclass instances."),
    InterviewQA("Interview", "Integer interning in CPython?", "Small ints (-5 to 256) may be cached; `is` may appear True for equal small ints."),
    InterviewQA("Interview", "Complex numbers in Python?", "`complex(real, imag)` with `.real`, `.imag`. Useful in signal processing."),
    InterviewQA("Interview", "What are variable annotations?", "Syntax `x: int = 0` for hints; stored in `__annotations__` on functions/modules."),
    InterviewQA("Interview", "Bytes vs str?", "`str` is Unicode text; `bytes` is raw binary. Encode/decode at I/O boundaries."),
    InterviewQA("Interview", "Floor vs truncation for negatives?", "`//` floors (-7//2 = -4). int(-7/2) truncates toward zero (-3)."),
    InterviewQA("Interview", "When use `divmod`?", "When you need quotient and remainder together — time conversions, pagination."),
    InterviewQA("Interview", "Explain augmented assignment.", "`x += 1` may call `__iadd__` in place for mutable types; not always same as `x = x + 1`."),
    InterviewQA("Interview", "Scientific notation literals?", "`1e-3` == 0.001; useful for ML learning rates."),
    InterviewQA("Interview", "Underscores in numeric literals?", "`1_000_000` readable; ignored by parser."),
    InterviewQA("Interview", "None as default argument pitfall?", "Mutable defaults shared across calls — use `None` sentinel instead."),
    InterviewQA("Interview", "How Python handles mixed-type ops?", "Follows coercion rules; int + float → float. Don't rely on implicit coercion in production."),
]

