    InterviewQA("Control flow", "What does loop else do?", "Runs if loop completes without break — useful for search-not-found."),
    InterviewQA("Functions", "*args vs **kwargs?", "*args collects positional extras as tuple; **kwargs collects keyword extras as dict."),
